import { expect, test } from "bun:test";
import { summarise } from "./subject.js";

const run = (ok: boolean) => ({ agent: "direct", instruction: "x", ok });
const foreign = () => ({ kind: "subagent", event: "stop", agent_id: "a1" });

test("foreign rows are not runs", () => {
  expect(summarise([foreign(), run(true), foreign(), run(false)]))
    .toEqual({ total: 2, passed: 1, failed: 1 });
});
test("a feed of only foreign rows has no runs", () => {
  expect(summarise([foreign(), foreign()])).toEqual({ total: 0, passed: 0, failed: 0 });
});
test("an empty feed is empty", () => {
  expect(summarise([])).toEqual({ total: 0, passed: 0, failed: 0 });
});
